  3	// The canonical English ledger values (D163) and the legacy spellings of earlier ledgers and exports.
  4	const KINDS = {
  5	  asset: 'Company thesis',
  6	  'Company view': 'Company thesis',
  7	  'Company thesis': 'Company thesis',
  8	  对象观点: 'Company thesis',
  9	  theme: 'Theme thesis',
 10	  'Theme view': 'Theme thesis',
 11	  'Theme thesis': 'Theme thesis',
 12	  主题观点: 'Theme thesis',
 13	};
 14	const TIERS = {
 15	  fact: 'Fact',
 16	  Fact: 'Fact',
 17	  发生的事: 'Fact',
 18	  party_statement: 'Party statement',
 19	  'Party statement': 'Party statement',
 20	  当事人说的: 'Party statement',
 21	  third_party_view: 'Third-party view',
 22	  'Third-party view': 'Third-party view',
 23	  第三方看法: 'Third-party view',
 24	  rumour: 'Rumour',
 25	  Rumour: 'Rumour',
 26	  传闻: 'Rumour',
 27	};
 28	const ORDINAL = ['+2', '+1', '0', '−1', '−2'];
 29	const YES_NO = { Yes: 'Yes', 是: 'Yes', No: 'No', 否: 'No' };
 30	function magnitude(condition) {
 31	  return [...condition.matchAll(/(\d[\d,.]*)\s*(万亿|千亿|亿)/g)].map(
 32	    (m) =>
 33	      Number(m[1].replaceAll(',', '')) * (m[2] === '万亿' ? 10000 : m[2] === '千亿' ? 1000 : 1),
 34	  );
 35	}
 36	// A rung's representative amount: its numeric bounds when the ledger carries them (every English-library rung does),
 37	// else the magnitudes written in its condition (legacy ledgers; condition_zh is the untranslated text).
 38	function representative(rung) {
 39	  const lo = typeof rung.lo === 'number' ? rung.lo : null;
 40	  const hi = typeof rung.hi === 'number' ? rung.hi : null;
 41	  if (lo !== null || hi !== null)
 42	    return lo !== null && hi !== null ? (lo + hi) / 2 : lo !== null ? lo : hi;
 43	  const values = magnitude(rung.condition_zh || rung.condition);
 44	  return values.length ? values.reduce((sum, n) => sum + n, 0) / values.length : NaN;
 45	}
 46	function legacyScores(view) {
 47	  if (view.rungs.every((r) => r.score)) return view.rungs.map((r) => r.score);
 48	  if (view.rungs.length === 2) {
 49	    // a yes/no ladder may list No first: each rung shows its own outcome; other two-rung labels keep their order
 50	    const own = view.rungs.map((r) => YES_NO[(r.label || '').trim()]);
 51	    return own.includes('Yes') && own.includes('No') ? own : ['Yes', 'No'];
 52	  }
 53	  if (KINDS[view.kind] === 'Theme thesis') {
 54	    const first = representative(view.rungs[0]);
 55	    const last = representative(view.rungs.at(-1));
 56	    if (last > first) return [...ORDINAL].reverse();
 57	  }
 58	  return ORDINAL;
 59	}
 60	function source(value = {}, day = null) {
 61	  return {
 62	    title: value.title || '',
 63	    publisher: value.publisher || '',
 64	    category: value.category || '',
 65	    uri: value.uri || value.source_uri || null,
 66	    publication_day: value.publication_day || day,
 67	  };
 68	}
 69	function array(value, path) {
 70	  if (!Array.isArray(value)) throw new ContractError(path, 'expected an array');
 71	  return value;
 72	}
 73	/** Compatibility boundary for mock JSON and POST /ideas view_bundle records. */
 74	export function fromBundles(input, options = {}) {
 75	  if (!input || !Array.isArray(input.views) || !Array.isArray(input.days))
 76	    throw new ContractError('/', 'bundle payload needs views and days arrays');
 77	  const sequenceDays = options.sequenceDays || input.sequence_days || {};
 78	  const dated = (day, seq, path) => {
 79	    const result = day || sequenceDays[seq];
 80	    if (!result)
 81	      throw new ContractError(path, 'missing event date; supply dated bundles or sequenceDays');
 82	    return result;
 83	  };
 84	  const theses = input.views.map((v, vi) => {
 85	    const path = `/views/${vi}`;
 86	    if (!v || typeof v !== 'object') throw new ContractError(path, 'expected a thesis bundle');
 87	    for (const key of ['rungs', 'judgements', 'evidence', 'dependencies', 'switches'])
 88	      array(v[key], `${path}/${key}`);
 89	    const scores = legacyScores(v);
 90	    return {
 91	      id: v.view_id,
 92	      object: v.object,
 93	      kind: KINDS[v.kind],
 94	      looks_at: v.looks_at,
 95	      question: v.question,
 96	      year: v.year ?? null,
 97	      identity: v.identity ?? null,
 98	      successions: v.successions ?? [],
 99	      due_day: v.due_day,
100	      created_seq: v.created_seq,
101	      created_day: dated(v.created_day, v.created_seq, `${path}/created_day`),
102	      created_from: source(v.created_from),
103	      rungs: v.rungs.map((r, i) => ({
104	        position: r.position,
105	        score: scores[i],
106	        label: r.label,
107	        condition: r.condition,
108	        ...(r.condition_zh ? { condition_zh: r.condition_zh } : {}),
109	        ...(typeof r.lo === 'number' ? { lo: r.lo } : {}),
110	        ...(typeof r.hi === 'number' ? { hi: r.hi } : {}),
111	      })),
112	      judgements: v.judgements
113	        .map((j, i) => ({
114	          id: j.id || `legacy:${v.view_id}:${i}`,
115	          day: j.day,
116	          seq: j.seq,
117	          rung: j.rung,
118	          changed: j.changed,
119	          why_changed: j.why_changed || '',
120	          reasons: j.reasons || '',
121	          cited: [...array(j.cited, `${path}/judgements/${i}/cited`)],
122	        }))
123	        .sort((a, b) => a.day.localeCompare(b.day) || a.seq - b.seq),
124	      evidence: v.evidence.map((e, i) => ({
125	        id: e.id,
126	        one_line: e.one_line,
127	        quote: e.quote,
128	        tier: TIERS[e.tier],
129	        speaker: e.speaker || '',
130	        original_who: e.original_who || '',
131	        original_date: e.original_day || '',
132	        event_time: e.event_time || '',
133	        day: e.day,
134	        arrival_day: dated(e.arrival_day, e.linked_seq, `${path}/evidence/${i}/arrival_day`),
135	        seq: e.seq,
136	        source: source(e.source, e.day),
137	        outlets: e.outlets,
138	        sources: (e.sources || []).map((s) => ({
139	          input_id: s.input_id,
140	          day: s.day,
141	          arrival_day: s.arrival_day,
142	          source: source(s.source, s.day),
143	        })),
144	        replaced_by: e.replaced_by ? { ...e.replaced_by, day: e.replaced_by.day ?? null } : null,
145	        replaces: e.replaces,
146	      })),
147	      dependencies: v.dependencies.map((d, i) => ({
148	        depends_on: d.depends_on,
149	        direction: d.direction,
150	        wait_year: d.wait_year,
151	        wait_chain_view_id: d.wait_chain_view_id ?? null,
152	        resolutions: d.resolutions ?? [],
153	        day: dated(d.day, d.seq, `${path}/dependencies/${i}/day`),
154	      })),
155	      switches: v.switches
156	        .map((s, i) => {
157	          if (![true, false, 0, 1].includes(s.open))
158	            throw new ContractError(
159	              `${path}/switches/${i}/open`,
160	              'expected a boolean or SQLite 0/1',
161	            );
162	          return {
163	            day: dated(s.day, s.after_seq, `${path}/switches/${i}/day`),
164	            seq: s.after_seq,
165	            open: s.open === true || s.open === 1,
166	            reason: s.reason,
167	          };
168	        })
169	        .sort((a, b) => a.day.localeCompare(b.day) || a.seq - b.seq),
170	    };
171	  });
172	  return parseDataset({
173	    schema_version: 'thesis-ui/2',
174	    coverage: input.coverage || 'selection',
175	    groups: input.groups ?? [],
176	    as_of: options.asOf || input.as_of || input.idea?.as_of || input.days.at(-1),
177	    days: [...input.days],
178	    theses,
179	  });
180	}
181	export function fromIdeaResponse(response) {
182	  return fromBundles(response, { asOf: response.idea.as_of });
183	}

